import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGob8Fzn.js";const u=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about react-native-universal-sheet - native vs JavaScript sheets, stacking, Expo, React Navigation, New Architecture, Reanimated and comparisons.","frontmatter":{"description":"Frequently asked questions about react-native-universal-sheet - native vs JavaScript sheets, stacking, Expo, React Navigation, New Architecture, Reanimated and comparisons.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-universal-sheet/reference/faq"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-universal-sheet/reference/faq"}],["meta",{"property":"og:title","content":"FAQ · React Native Universal Sheet"}],["meta",{"property":"og:description","content":"Frequently asked questions about react-native-universal-sheet - native vs JavaScript sheets, stacking, Expo, React Navigation, New Architecture, Reanimated and comparisons."}],["meta",{"name":"twitter:title","content":"FAQ · React Native Universal Sheet"}],["meta",{"name":"twitter:description","content":"Frequently asked questions about react-native-universal-sheet - native vs JavaScript sheets, stacking, Expo, React Navigation, New Architecture, Reanimated and comparisons."}]]},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1794234315000}'),n={name:"reference/faq.md"};function i(s,e,h,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h3 id="is-this-a-javascript-bottom-sheet-or-a-native-one" tabindex="-1">Is this a JavaScript bottom sheet or a native one? <a class="header-anchor" href="#is-this-a-javascript-bottom-sheet-or-a-native-one" aria-label="Permalink to &quot;Is this a JavaScript bottom sheet or a native one?&quot;">​</a></h3><p>Native. On iOS the sheet is presented by UIKit (<code>UISheetPresentationController</code>), on Android by Material&#39;s <code>BottomSheetDialog</code>. React renders only your content. On the web it is a DOM dialog.</p><h3 id="do-i-need-reanimated-or-gesture-handler" tabindex="-1">Do I need Reanimated or Gesture Handler? <a class="header-anchor" href="#do-i-need-reanimated-or-gesture-handler" aria-label="Permalink to &quot;Do I need Reanimated or Gesture Handler?&quot;">​</a></h3><p>No. Gestures and animation come from the platform.</p><h3 id="can-i-open-a-bottom-sheet-on-top-of-another" tabindex="-1">Can I open a bottom sheet on top of another? <a class="header-anchor" href="#can-i-open-a-bottom-sheet-on-top-of-another" aria-label="Permalink to &quot;Can I open a bottom sheet on top of another?&quot;">​</a></h3><p>Yes. That&#39;s the default (<code>presentation: &#39;stack&#39;</code>). Closing the top sheet shows the one beneath with its state intact. See <a href="/react-native-universal-sheet/features/stacking">Stacking</a>.</p><h3 id="does-it-work-with-expo" tabindex="-1">Does it work with Expo? <a class="header-anchor" href="#does-it-work-with-expo" aria-label="Permalink to &quot;Does it work with Expo?&quot;">​</a></h3><p>Yes, in a development build or EAS build, with the config plugin in <code>app.json</code>. Not in Expo Go. See <a href="/react-native-universal-sheet/installation/expo">Expo</a>.</p><h3 id="does-it-work-with-react-navigation-and-expo-router" tabindex="-1">Does it work with React Navigation and Expo Router? <a class="header-anchor" href="#does-it-work-with-react-navigation-and-expo-router" aria-label="Permalink to &quot;Does it work with React Navigation and Expo Router?&quot;">​</a></h3><p>Yes. Put the provider at the root. See <a href="/react-native-universal-sheet/recipes/react-navigation">React Navigation</a>.</p><h3 id="does-it-support-the-new-architecture" tabindex="-1">Does it support the New Architecture? <a class="header-anchor" href="#does-it-support-the-new-architecture" aria-label="Permalink to &quot;Does it support the New Architecture?&quot;">​</a></h3><p>The library ships a codegen spec and classic view managers. Android works through the interop layer. iOS has no Fabric component view yet, so it relies on the legacy interop layer, which has not been verified on a device. See <a href="/react-native-universal-sheet/reference/compatibility">Compatibility</a>.</p><h3 id="does-it-work-on-the-web" tabindex="-1">Does it work on the web? <a class="header-anchor" href="#does-it-work-on-the-web" aria-label="Permalink to &quot;Does it work on the web?&quot;">​</a></h3><p>Yes, with <code>react-native-web</code> and <code>react-dom</code>. Every placement is drawn on the web, including the ones not yet native. See <a href="/react-native-universal-sheet/installation/web">Web</a>.</p><h3 id="can-i-use-it-without-the-provider" tabindex="-1">Can I use it without the provider? <a class="header-anchor" href="#can-i-use-it-without-the-provider" aria-label="Permalink to &quot;Can I use it without the provider?&quot;">​</a></h3><p>No. Hooks and components throw a clear error without it.</p><h3 id="can-i-open-a-sheet-from-outside-a-component" tabindex="-1">Can I open a sheet from outside a component? <a class="header-anchor" href="#can-i-open-a-sheet-from-outside-a-component" aria-label="Permalink to &quot;Can I open a sheet from outside a component?&quot;">​</a></h3><p>Yes. Create a <a href="/react-native-universal-sheet/components/sheet-manager"><code>SheetManager</code></a>, pass it to the provider, and call it from anywhere.</p><h3 id="what-is-the-difference-between-a-bottom-sheet-and-a-modal" tabindex="-1">What is the difference between a bottom sheet and a modal? <a class="header-anchor" href="#what-is-the-difference-between-a-bottom-sheet-and-a-modal" aria-label="Permalink to &quot;What is the difference between a bottom sheet and a modal?&quot;">​</a></h3><p>A bottom sheet slides up from the bottom edge and can rest at several heights. A modal is a dialog centred (or placed) over the screen. Both are available: <a href="/react-native-universal-sheet/components/native-sheet"><code>NativeSheet</code></a> and <a href="/react-native-universal-sheet/components/native-modal"><code>NativeModal</code></a>.</p><h3 id="why-does-present-return-an-object-instead-of-throwing" tabindex="-1">Why does <code>present()</code> return an object instead of throwing? <a class="header-anchor" href="#why-does-present-return-an-object-instead-of-throwing" aria-label="Permalink to &quot;Why does `present()` return an object instead of throwing?&quot;">​</a></h3><p>So a double tap or a bad config never crashes the app. Check <code>result.ok</code> when you care. See <a href="/react-native-universal-sheet/reference/errors">Error reasons</a>.</p><h3 id="is-it-production-ready" tabindex="-1">Is it production-ready? <a class="header-anchor" href="#is-it-production-ready" aria-label="Permalink to &quot;Is it production-ready?&quot;">​</a></h3><p>Not yet. Version 0.1.0 has a complete, tested TypeScript API and web renderer. The native code hasn&#39;t been verified on devices. See <a href="/react-native-universal-sheet/reference/roadmap">Status &amp; roadmap</a>.</p>',25)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
